/**
 * Server-side feature gating.
 *
 * DEV MODE (current): all server-side gates are pass-through — every feature is
 * open to every plan. Badges in the sidebar/nav are still computed via static
 * `hasFeature()` for visual indication of "this would be gated in prod".
 *
 * To re-enable restrictions: revert `requireFeatureRpc`, `checkFeatureRpc`, and
 * `requireFeature` to their original RPC-backed implementations (see git history).
 *
 * NEVER call check_feature_access from Client Components — server-side only.
 */

import type { SupabaseClient } from '@supabase/supabase-js'
import { logger } from '@/lib/logger'

export type PlanTier = 'solo' | 'studio' | 'pro' | 'enterprise'

export const PLAN_ORDER: Record<PlanTier, number> = {
  solo: 0,
  studio: 1,
  pro: 2,
  enterprise: 3,
}

/**
 * Canonical set of feature keys — must match the plan features JSONB in the DB.
 * If this set drifts from DB values, requireFeatureRpc() will universally 403.
 * Run warnOnFeatureKeyDrift() at startup to surface any mismatch early.
 */
export const KNOWN_FEATURE_KEYS = new Set([
  'booking',
  'calendar',
  'public_booking_page',
  'digital_consent',
  'client_crm',
  'dodo_payments',
  'inventory',
  'commissions',
  'payroll',
  'ai_design',
  'ai_design_assistant',
  'guest_artists',
  'eu_reach',
  'multi_location',
  'custom_domain',
  'api_access',
  'sms_reminders',
  'analytics',
  'white_label',
  'marketing_basic',
  'marketing_advanced',
  'calendar_sync',
  'referral_program',
  'omnichannel_inbox',
  'messaging_ai_replies',
  'projects',
  'flash_events',
])

/**
 * Called at server startup (e.g. instrumentation.ts) to warn if plan JSONB
 * contains keys not in KNOWN_FEATURE_KEYS — catches future key drift early.
 * Never throws; degraded gracefully.
 */
export async function warnOnFeatureKeyDrift(supabase: SupabaseClient): Promise<void> {
  try {
    const { data, error } = await supabase
      .from('plans')
      .select('name, features')
      .eq('is_active', true)
    if (error || !data) return

    for (const plan of data) {
      const keys = plan.features as string[] | null
      if (!Array.isArray(keys)) continue
      for (const key of keys) {
        if (!KNOWN_FEATURE_KEYS.has(key)) {
          logger.warn(
            { plan: plan.name, unknownKey: key },
            'feature-gate: plan contains unknown feature key — check_feature_access may 403 unexpectedly',
          )
        }
      }
    }
  } catch {
    // Startup check — never block server init
  }
}

/** Minimum plan required for each feature key (static fallback) */
const FEATURE_MIN_PLAN: Record<string, PlanTier> = {
  inventory: 'studio',
  commissions: 'studio',
  payroll: 'pro',
  ai_design: 'pro',
  ai_design_assistant: 'pro',
  guest_artists: 'pro',
  eu_reach: 'pro',
  multi_location: 'pro',
  white_label: 'enterprise',
  api_access: 'enterprise',
  sms_reminders: 'studio',
  analytics: 'studio',
  marketing_basic: 'studio',
  marketing_advanced: 'studio',
  calendar_sync: 'studio',
  referral_program: 'studio',
  omnichannel_inbox: 'studio',
  messaging_ai_replies: 'pro',
  projects: 'pro',
  flash_events: 'studio',
}

// ---------------------------------------------------------------------------
// Static helpers (no DB round-trip)
// ---------------------------------------------------------------------------

export function hasFeature(plan: PlanTier, feature: string): boolean {
  const minPlan = FEATURE_MIN_PLAN[feature]
  if (!minPlan) return true
  return PLAN_ORDER[plan] >= PLAN_ORDER[minPlan]
}

export function requiredPlanFor(feature: string): PlanTier | null {
  return FEATURE_MIN_PLAN[feature] ?? null
}

// DEV MODE: pass-through. Always returns null (allow access).
// Re-enable by reverting to the original plan-comparison + 403 response.
export function requireFeature(_plan: PlanTier, _feature: string): Response | null {
  return null
}

// ---------------------------------------------------------------------------
// Custom error for RPC-based gating
// ---------------------------------------------------------------------------

export class FeatureGateError extends Error {
  readonly featureKey: string
  constructor(featureKey: string) {
    super(`Feature '${featureKey}' is not available on current plan`)
    this.name = 'FeatureGateError'
    this.featureKey = featureKey
  }
}

// ---------------------------------------------------------------------------
// RPC-based gating (server components + API routes)
// ---------------------------------------------------------------------------

/**
 * DEV MODE: pass-through. Never throws.
 * Re-enable by reverting to the RPC-backed implementation.
 */
export async function requireFeatureRpc(
  _supabase: SupabaseClient,
  _studioId: string,
  _featureKey: string,
): Promise<void> {
  return
}

/**
 * DEV MODE: always returns true.
 * Re-enable by reverting to the RPC-backed implementation.
 */
export async function checkFeatureRpc(
  _supabase: SupabaseClient,
  _studioId: string,
  _featureKey: string,
): Promise<boolean> {
  return true
}

/**
 * Static OG image for the root page (waitlist / marketing).
 * 1200×630 per Open Graph spec.
 */
import { ImageResponse } from 'next/og'

export const runtime = 'edge'

export const alt = 'InkOS — Tattoo Studio Operating System'
export const size = { width: 1200, height: 630 }
export const contentType = 'image/png'

export default function Image() {
  return new ImageResponse(
    (
      <div
        style={{
