// ── Editor Dialog ────────────────────────────────────────────────────────────

interface EditorDialogProps {
  tag: StyleTag | null
  open: boolean
  onOpenChange: (open: boolean) => void
  onSaved: () => void
}

function StyleTagEditor({ tag, open, onOpenChange, onSaved }: EditorDialogProps) {
  const isEdit = !!tag
  const [name, setName] = useState(tag?.name ?? '')
  const [color, setColor] = useState<string>(tag?.color ?? PRESET_COLORS[0] ?? '#6366f1')
  const [description, setDescription] = useState(tag?.description ?? '')
  const [saving, setSaving] = useState(false)

  // Reset form when tag prop changes
  useEffect(() => {
    setName(tag?.name ?? '')
    setColor(tag?.color ?? PRESET_COLORS[0] ?? '#6366f1')
    setDescription(tag?.description ?? '')
  }, [tag])

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault()
    if (!name.trim()) return

    setSaving(true)
    try {
      const url = isEdit ? `/api/style-tags/${tag.id}` : '/api/style-tags'
      const method = isEdit ? 'PATCH' : 'POST'

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name.trim(), color, description: description || null }),
      })

      if (!res.ok) {
        const j = await res.json() as { error?: string }
        throw new Error(j.error ?? 'Failed to save')
      }

      toast.success(isEdit ? 'Style tag updated' : 'Style tag created')
      onSaved()
      onOpenChange(false)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save style tag')
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-sm">
        <DialogHeader>
          <DialogTitle>{isEdit ? 'Edit style tag' : 'New style tag'}</DialogTitle>
        </DialogHeader>

        <form onSubmit={(e) => void handleSubmit(e)} className="space-y-4 py-2">
          <div className="space-y-1.5">
            <Label htmlFor="st-name">Name *</Label>
            <Input
              id="st-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Fine Line"
              maxLength={80}
              required
            />
          </div>

          <div className="space-y-1.5">
            <Label>Color</Label>
            <div className="flex flex-wrap gap-1.5">
              {PRESET_COLORS.map((c) => (
                <button
                  key={c}
                  type="button"
                  className={cn(
                    'h-6 w-6 rounded-full border-2 transition-all',
                    color === c ? 'border-foreground scale-110' : 'border-transparent hover:scale-105'
                  )}
                  style={{ backgroundColor: c }}
                  onClick={() => setColor(c)}
                  aria-label={`Select color ${c}`}
                />
              ))}
              <input
                type="color"
                value={color}
                onChange={(e) => setColor(e.target.value)}
                className="h-6 w-6 rounded-full border-2 border-transparent cursor-pointer"
                title="Custom color"
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <Label htmlFor="st-desc">Description</Label>
            <Input
              id="st-desc"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="Optional description"
              maxLength={300}
            />
          </div>

          {/* Preview */}
          <div className="flex items-center gap-2 p-2.5 rounded-lg bg-muted/40">
            <span className="text-xs text-muted-foreground">Preview:</span>
            <span className="inline-flex items-center gap-1 rounded-full border border-border/60 px-2.5 py-0.5 text-xs font-medium">
              {color && (
                <span
                  className="h-1.5 w-1.5 rounded-full shrink-0"
                  style={{ backgroundColor: color }}
                />
              )}
              {name || 'Tag name'}
            </span>
          </div>

          <DialogFooter>
            <Button variant="outline" type="button" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={saving || !name.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {isEdit ? 'Save changes' : 'Create tag'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

