export function StyleTagsManager() {
  const [tags, setTags] = useState<StyleTag[]>([])
  const [loading, setLoading] = useState(true)
  const [editorOpen, setEditorOpen] = useState(false)
  const [editingTag, setEditingTag] = useState<StyleTag | null>(null)

  const fetchTags = useCallback(async () => {
    setLoading(true)
    try {
      const res = await fetch('/api/style-tags')
      if (!res.ok) throw new Error('Failed to load')
      const j = await res.json() as { data: StyleTag[] }
      setTags(j.data ?? [])
    } catch {
      toast.error('Failed to load style tags')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => { void fetchTags() }, [fetchTags])

  const openCreate = () => {
    setEditingTag(null)
    setEditorOpen(true)
  }

  const openEdit = (tag: StyleTag) => {
    setEditingTag(tag)
    setEditorOpen(true)
  }

  const handleDelete = async (tagId: string) => {
    try {
      const res = await fetch(`/api/style-tags/${tagId}`, { method: 'DELETE' })
      if (!res.ok) throw new Error('Delete failed')
      toast.success('Style tag deleted')
      setTags((prev) => prev.filter((t) => t.id !== tagId))
    } catch {
      toast.error('Failed to delete style tag')
