                      </AlertDialogContent>
                    </AlertDialog>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <StyleTagEditor
        tag={editingTag}
        open={editorOpen}
        onOpenChange={setEditorOpen}
        onSaved={() => void fetchTags()}
      />
