import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { evaluateAndEnqueueAutoSends } from '@/lib/consent/evaluate-auto-send-rules'

const ListBookingsSchema = z.object({
  from: z.string().datetime().optional(),
  to: z.string().datetime().optional(),
  artist_id: z.string().uuid().optional(),
  client_id: z.string().uuid().optional(),
  status: z
    .enum(['pending', 'confirmed', 'in_progress', 'completed', 'cancelled', 'no_show'])
    .optional(),
  page: z.coerce.number().int().min(1).default(1),
  per_page: z.coerce.number().int().min(1).max(100).default(50),
  q: z.string().max(200).optional(),
})

const CreateBookingSchema = z.object({
  client_id: z.string().uuid(),
  artist_id: z.string().uuid(),
  service_id: z.string().uuid().optional(),
  location_id: z.string().uuid().optional(),
  scheduled_at: z.string().datetime(),
  duration_min: z.number().int().min(15).max(480),
  price_cents: z.number().int().min(0),
  deposit_cents: z.number().int().min(0).optional(),
  notes: z.string().max(2000).optional(),
  source: z.enum(['internal', 'waitlist']).default('internal'),
  /** Direct project linkage — attach booking to an existing project.
   *  server verifies client_id matches project.client_id (studio-scoped via RLS).
   *  Takes precedence over link_booking_id if both are provided. */
  project_id: z.string().uuid().nullable().optional(),
  /** Smart-linking — when set, the new booking inherits project_id from the
   *  referenced booking and increments session_number by 1. Surfaces the
   *  multi-session project continuity per PDF spec. */
  link_booking_id: z.string().uuid().optional(),
})

export async function GET(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  const { searchParams } = new URL(request.url)
  const parsed = ListBookingsSchema.safeParse(Object.fromEntries(searchParams))
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { from, to, artist_id, client_id, status, page, per_page, q } = parsed.data
  const offset = (page - 1) * per_page

  try {
    const supabase = await createClient()
    let query = supabase
      .from('bookings')
      .select(
        `
        id, scheduled_at, end_at, duration_min, status, price_cents,
        deposit_cents, deposit_paid, project_id, session_number,
        booking_token, source, notes, created_at,
        client:clients(id, first_name, last_name, email, phone),
        artist:artists(id, display_name, avatar_url, sort_order),
        service:services(id, name, duration_min, color),
        project:projects(name)
      `,
        { count: 'exact' }
      )
      .eq('studio_id', authUser.studioId)
      .order('scheduled_at', { ascending: false })
      .range(offset, offset + per_page - 1)

    if (from) query = query.gte('scheduled_at', from)
    if (to) query = query.lte('scheduled_at', to)
    if (artist_id) query = query.eq('artist_id', artist_id)
    if (client_id) query = query.eq('client_id', client_id)
    if (status) query = query.eq('status', status)
    if (q) query = query.textSearch('fts', q, { type: 'websearch' })

    const { data, error, count } = await query

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'bookings list failed')
      return NextResponse.json({ error: 'Failed to fetch bookings' }, { status: 500 })
    }

    return NextResponse.json({
      data: data ?? [],
      count: count ?? 0,
      page,
      per_page,
      total_pages: Math.ceil((count ?? 0) / per_page),
    })
  } catch (err) {
    logger.error({ err }, 'bookings GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateBookingSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { client_id, artist_id, service_id, location_id, scheduled_at, duration_min, price_cents, deposit_cents, notes, source, project_id: directProjectId, link_booking_id } = parsed.data

  try {
    const supabase = await createClient()

    // Project linkage — direct project_id takes precedence over smart-link.
    // For direct: verify client_id matches project.client_id for integrity.
    // For smart-link: inherit project_id + increment session_number.
    let linkedProjectId: string | null = null
    let linkedSessionNumber: number | null = null

    if (directProjectId) {
      // Direct project linkage — verify ownership and client match
      const { data: linkedProject } = await supabase
        .from('projects')
        .select('id, client_id')
        .eq('id', directProjectId)
        .eq('studio_id', authUser.studioId)
        .maybeSingle()

      if (linkedProject) {
        if (linkedProject.client_id !== client_id) {
          return NextResponse.json(
            { error: 'project client does not match booking client' },
            { status: 422 }
          )
        }
        linkedProjectId = linkedProject.id
      }
    } else if (link_booking_id) {
      // Smart-linking — inherit project_id + next session_number from referenced booking
      const { data: linked } = await supabase
        .from('bookings')
        .select('project_id, session_number')
        .eq('id', link_booking_id)
        .eq('studio_id', authUser.studioId)
        .single()
      if (linked?.project_id) {
        linkedProjectId = linked.project_id
        linkedSessionNumber = (linked.session_number ?? 1) + 1
      }
    }

    const { data, error } = await supabase
      .from('bookings')
      .insert({
        studio_id: authUser.studioId,
        client_id,
        artist_id,
        service_id: service_id ?? null,
        location_id: location_id ?? null,
        scheduled_at,
        duration_min,
        price_cents,
        deposit_cents: deposit_cents ?? 0,
        notes: notes ?? null,
        source,
        status: 'pending' as const,
        ...(linkedProjectId
          ? {
              project_id: linkedProjectId,
              session_number: linkedSessionNumber,
            }
          : {}),
      })
      .select(
        `id, scheduled_at, end_at, duration_min, status, price_cents, deposit_paid, booking_token,
         client:clients(id, first_name, last_name, email),
         artist:artists(id, display_name),
         service:services(id, name)`
      )
      .single()

    if (error) {
      if (error.code === '23P01') {
        return NextResponse.json(
          { error: 'That time slot is already booked for this artist' },
          { status: 409 }
        )
      }
      logger.error({ err: error, studioId: authUser.studioId }, 'booking create failed')
      return NextResponse.json({ error: 'Failed to create booking' }, { status: 500 })
    }

    // S24c — evaluate consent auto-send rules. Non-fatal: errors are
    // logged inside the evaluator and never bubble up. A booking always
    // succeeds even if rule evaluation breaks. Evaluator builds its own
    // service-role client (M6) — safe after response return.
    void evaluateAndEnqueueAutoSends({
      event: 'booking_created',
      bookingId: data.id,
      clientId: client_id,
      studioId: authUser.studioId,
      scheduledAt: data.scheduled_at,
    })

    return NextResponse.json({ data }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'bookings POST unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { redirect } from 'next/navigation'
import { PermissionsMatrix } from '@/components/settings/team/PermissionsMatrix'
import { Typography } from '@/components/ui/typography'
import { getActiveStudio, NoStudioMembershipError } from '@/lib/context/active-studio'
import { resolveSettingsLandingHref } from '@/lib/settings/navigation'
import { createClient } from '@/lib/supabase/server'
import { getUserPermissions } from '@/lib/team/permissions'

export default async function TeamPermissionsPage() {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) {
    redirect('/login')
  }

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) {
      redirect('/onboarding')
    }
    redirect('/onboarding')
  }

  const permissions = await getUserPermissions(activeStudio.studioId, user.id)

  if (!permissions.has('settings.team')) {
    redirect(resolveSettingsLandingHref(permissions))
  }

  const canEdit = permissions.has('admin.change_roles')
  const isPro = activeStudio.plan === 'pro' || activeStudio.plan === 'enterprise'

  return (
    <div className="space-y-6">
      <div className="space-y-2">
        <Typography variant="h2">Roles &amp; permissions</Typography>
        <p className="text-sm text-muted-foreground">
          Decide who can manage bookings, clients, billing, and studio controls.
        </p>
      </div>

      {!canEdit && (
        <div className="rounded-2xl border border-border/60 bg-muted/35 px-4 py-3">
          <p className="text-sm font-medium text-foreground">View-only access</p>
          <p className="mt-1 text-sm text-muted-foreground">
            You can review role access here, but only owners can change permissions.
          </p>
        </div>
      )}

      <PermissionsMatrix isPro={isPro} canEdit={canEdit} />
    </div>
  )
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient, createServiceRoleClient } from '@/lib/supabase/server'
