/** Generates a random 8-char lowercase suffix for role_key uniqueness */
function randomSuffix(): string {
  return Math.random().toString(36).slice(2, 10).toLowerCase()
}

/** Converts a display name to a URL-safe slug */
function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 24)
}

const CreateCustomRoleSchema = z.object({
  display_name: z.string().min(1).max(50).trim(),
  cloned_from: z.enum(['owner', 'admin', 'artist', 'receptionist', 'guest_artist']),
  description: z.string().max(200).optional(),
})

/**
 * POST /api/custom-roles
 * Creates a new custom role by cloning permissions from a preset role.
 * Owner-only. Pro+ plan required.
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner') {
    return NextResponse.json({ error: 'Owner role required' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = CreateCustomRoleSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const { display_name, cloned_from, description } = parsed.data

  // Plan gate: custom roles require pro+
  const supabase = await createClient()
  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', authUser.studioId)
    .eq('status', 'active')
    .maybeSingle()

  const plan = sub?.plan_tier ?? 'solo'
  if (plan === 'solo' || plan === 'studio') {
    return NextResponse.json(
      { error: 'Custom roles require Pro or Enterprise plan' },
      { status: 403 },
    )
  }

  // Generate unique role_key
  const slug = slugify(display_name)
  const suffix = randomSuffix()
  const role_key = `custom:${slug}_${suffix}`

  try {
    // Use service-role to bypass RLS for role_permissions copy
    const serviceClient = createServiceRoleClient()

    // Insert the custom role record
    const { data: newRole, error: roleError } = await serviceClient
      .from('studio_custom_roles')
      .insert({
        studio_id: authUser.studioId,
        role_key,
        display_name,
        cloned_from,
        ...(description != null ? { description } : {}),
        created_by: authUser.user.id,
      })
      .select()
      .single()

    if (roleError) {
      logger.error({ err: roleError }, 'custom-roles: insert failed')
      return NextResponse.json({ error: 'Failed to create custom role' }, { status: 500 })
    }

    // Copy permission rows from the source role
    const { data: sourcePerms, error: permsError } = await serviceClient
      .from('role_permissions')
      .select('permission_key, granted')
      .eq('role', cloned_from)

    if (permsError) {
      logger.error({ err: permsError }, 'custom-roles: source perms fetch failed')
      // Role was created — return it but warn about missing perms
      return NextResponse.json({ data: newRole, warning: 'Permissions could not be copied' })
    }

    if ((sourcePerms ?? []).length > 0) {
      const newPerms = (sourcePerms ?? []).map((p) => ({
        role: role_key,
        permission_key: p.permission_key,
        granted: p.granted,
      }))

      const { error: insertPermsError } = await serviceClient
        .from('role_permissions')
        .insert(newPerms)

      if (insertPermsError) {
        logger.error({ err: insertPermsError }, 'custom-roles: permission copy failed')
      }
    }

    await logAuditAction(
      authUser.user.id,
      'custom_role.created',
      { type: 'studio_custom_role', id: newRole.id },
      { role_key, cloned_from, display_name },
      authUser.studioId,
    )

    return NextResponse.json({ data: newRole }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'custom-roles POST failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * GET /api/custom-roles
 * Returns all custom roles for the current studio.
 */
export async function GET(_request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  if (authUser.role !== 'owner' && authUser.role !== 'admin') {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  try {
    const supabase = await createClient()
    const { data, error } = await supabase
      .from('studio_custom_roles')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .order('created_at', { ascending: true })

    if (error) {
      return NextResponse.json({ error: 'Failed to fetch custom roles' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'custom-roles GET failed')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * Rate limiters — Upstash Ratelimit.
 *
 * Falls back to a permissive no-op limiter when UPSTASH_REDIS_REST_URL /
 * UPSTASH_REDIS_REST_TOKEN are absent (local dev without Redis).
 *
 * Production MUST have both env vars set or all limiters will always allow
 * requests — the startup check in lib/env.ts will warn in that case.
 */
import { logger } from '@/lib/logger'

// ─── Limiter interface (matches Upstash RatelimitResponse shape) ────────────
export interface RateLimitResponse {
  success: boolean
  limit: number
  remaining: number
  reset: number
}

export interface Limiter {
  limit: (identifier: string) => Promise<RateLimitResponse>
}

// ─── No-op fallback (used when Redis env vars absent) ───────────────────────
function makeNoop(name: string): Limiter {
  let warned = false
  return {
    async limit() {
      if (!warned) {
        logger.warn(
          { limiter: name },
          'rate-limit: UPSTASH_REDIS_REST_URL not set — limiter is permissive (dev mode)',
        )
        warned = true
      }
      return { success: true, limit: 9999, remaining: 9999, reset: Date.now() + 60_000 }
    },
  }
}

// ─── Real Upstash limiter factory ────────────────────────────────────────────
function makeUpstashLimiter(
  requests: number,
  windowSeconds: number,
  name: string,
): Limiter {
  const url = process.env.UPSTASH_REDIS_REST_URL
  const token = process.env.UPSTASH_REDIS_REST_TOKEN

  if (!url || !token) {
    return makeNoop(name)
  }

  // Sliding window via Upstash REST API — no Node.js SDK dependency needed.
  // Uses the MULTI/EXEC pattern: INCR + EXPIRE in one round-trip.
  return {
    async limit(identifier: string): Promise<RateLimitResponse> {
      const key = `rl:${name}:${identifier}`
      const now = Date.now()
      const windowMs = windowSeconds * 1_000

      try {
        // Pipeline: INCR key + EXPIRE key windowSeconds
        const pipelineRes = await fetch(`${url}/pipeline`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify([
            ['INCR', key],
            ['EXPIRE', key, windowSeconds],
          ]),
        })

        if (!pipelineRes.ok) {
          logger.warn({ name, status: pipelineRes.status }, 'rate-limit: Upstash pipeline error — allowing request')
          return { success: true, limit: requests, remaining: requests, reset: now + windowMs }
        }

        const results = await pipelineRes.json() as [{ result: number }, { result: number }]
        const count = results[0].result

        const remaining = Math.max(0, requests - count)
        const reset = now + windowMs

        if (count > requests) {
          return { success: false, limit: requests, remaining: 0, reset }
        }

        return { success: true, limit: requests, remaining, reset }
      } catch (err) {
        // On Redis error: fail open (allow) and log
        logger.error({ err, name }, 'rate-limit: Redis error — failing open')
        return { success: true, limit: requests, remaining: requests, reset: now + windowMs }
      }
    },
  }
}

// ─── Exported limiters ───────────────────────────────────────────────────────
// Adjust windows and limits per endpoint risk profile.

/** Generic authenticated API calls — 120 req/min per IP */
export const apiRatelimit = makeUpstashLimiter(120, 60, 'api')

/** Authenticated actions (CRUD) — 60 req/min per IP */
export const authedRatelimit = makeUpstashLimiter(60, 60, 'authed')

/** Expensive operations (AI generation, PDF export, reports) — 10 req/min */
export const expensiveRatelimit = makeUpstashLimiter(10, 60, 'expensive')

/** Login attempts — 10 per 15 minutes per IP (brute-force protection) */
export const loginRatelimit = makeUpstashLimiter(10, 900, 'login')

/** Signup attempts — 5 per 15 minutes per IP (spam protection) */
export const signupRatelimit = makeUpstashLimiter(5, 900, 'signup')

/** Forgot-password requests — 5 per 15 minutes per IP */
export const forgotPasswordRatelimit = makeUpstashLimiter(5, 900, 'forgot-password')

/** Public booking page reads — 60 req/min per IP */
export const publicBookingReadRatelimit = makeUpstashLimiter(60, 60, 'public-booking-read')

/** Public booking submissions — 10 per 10 minutes per IP */
export const publicBookingCreateRatelimit = makeUpstashLimiter(10, 600, 'public-booking-create')

/** Public consent form reads — 30 req/min per IP */
export const publicConsentReadRatelimit = makeUpstashLimiter(30, 60, 'public-consent-read')

/** Public consent form submissions — 5 per 10 minutes per IP */
export const publicConsentSubmitRatelimit = makeUpstashLimiter(5, 600, 'public-consent-submit')

