@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

@custom-variant dark (&:is(.dark *));

@theme inline {
  /* ──────────────────────────────────────────────────────────
     INKOS BRAND SWATCHES — Brand Book v1.0 (LOCKED)
     Bone · Onyx · Stone · Rust — no additions, no substitutes
  ────────────────────────────────────────────────────────── */
  --color-bone: #F7F7F5;
  --color-onyx: #0F0F0F;
  --color-stone: #787774;
  --color-rust: #B23A2B;

  --font-sans: var(--font-sans), 'Inter', -apple-system, sans-serif;
  --font-serif: var(--font-serif), 'Instrument Serif', Georgia, serif;
  --font-mono: var(--font-mono), 'JetBrains Mono', monospace;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC PALETTE — derived from brand swatches
     Rule: never pure #FFF or #000. Bone/Onyx only.
  ────────────────────────────────────────────────────────── */

  /* Bone — 60% usage. Page canvas + sidebar bg. */
  --color-background: #F7F7F5;

  /* Onyx — 20% usage. Primary text + CTAs. */
  --color-foreground: #0F0F0F;

  /* Card surface — pure white on Bone, so cards "float" */
  --color-card: #FFFFFF;
  --color-card-foreground: #0F0F0F;

  --color-popover: #FFFFFF;
  --color-popover-foreground: #0F0F0F;

  /* Primary = Onyx (NOT Rust). Primary CTAs are black. */
  --color-primary: #0F0F0F;
  --color-primary-foreground: #F7F7F5;

  /* Secondary — muted Bone tint */
  --color-secondary: oklch(96% 0.003 60);
  --color-secondary-foreground: #0F0F0F;

  /* Muted — Stone-tinted backgrounds */
  --color-muted: oklch(95% 0.003 60);
  --color-muted-foreground: #787774;

  /* Accent — Rust at 12% opacity for active nav states */
  --color-accent: rgba(178, 58, 43, 0.08);
  --color-accent-foreground: #B23A2B;

  /* Destructive = Rust. Reserved for LIVE pill, active nav, destructive only. */
  --color-destructive: #B23A2B;
  --color-destructive-foreground: #F7F7F5;

  /* ──────────────────────────────────────────────────────────
     SEMANTIC STATUS TOKENS
  ────────────────────────────────────────────────────────── */
  --color-success:            oklch(58% 0.18 145);
  --color-success-bg:         oklch(94% 0.05 145);
  --color-success-foreground: oklch(26% 0.12 145);
  --color-warning:            oklch(70% 0.16 72);
  --color-warning-bg:         oklch(94% 0.07 72);
  --color-warning-foreground: oklch(36% 0.15 72);

  /* Borders — Stone-tinted, warm hue, tuned to be visible on bone canvas */
  --color-border: oklch(91% 0.005 85);
  --color-input: oklch(91% 0.005 85);
  --color-ring: #0F0F0F;

  /* ──────────────────────────────────────────────────────────
     SHADOWS — custom (never use Tailwind default shadow-sm/md)
  ────────────────────────────────────────────────────────── */

  /* Soft border shadow for cards on white — bumped alpha so cards read on bone bg */
  --shadow-soft: 0 1px 2px 0 oklch(20% 0.02 85 / 0.08), 0 1px 3px 0 oklch(20% 0.02 85 / 0.05);

  /* Standard card elevation — visible on off-white page */
  --shadow-card: 0 1px 3px 0 oklch(20% 0.02 85 / 0.10), 0 2px 4px -1px oklch(20% 0.02 85 / 0.06);

  /* Hover elevation */
  --shadow-card-hover: 0 6px 16px -4px oklch(20% 0.02 85 / 0.14), 0 3px 8px -2px oklch(20% 0.02 85 / 0.09);

  /* Medium depth for drawers, modals */
  --shadow-soft-md: 0 4px 16px -4px oklch(13% 0.015 85 / 0.10), 0 2px 8px -2px oklch(13% 0.015 85 / 0.07);

  /* Floating elements — command palette, toasts, tooltips */
  --shadow-lift: 0 8px 24px -4px oklch(13% 0.015 85 / 0.14),
                 0 4px 10px -2px oklch(13% 0.015 85 / 0.08);

  /* Full-screen overlays — modal backdrop shadow on dialog */
  --shadow-overlay: 0 24px 64px -12px oklch(13% 0.015 85 / 0.22),
                    0 8px 24px -4px oklch(13% 0.015 85 / 0.12);

  /* ──────────────────────────────────────────────────────────
     RADIUS
  ────────────────────────────────────────────────────────── */
  --radius: 0.5rem;
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;   /* 24px — large modals, full-bleed cards */
  --radius-full: 9999px;  /* pill buttons, avatar chips, progress bars */

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY
  ────────────────────────────────────────────────────────── */
  --font-sans: var(--font-geist-sans), system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: var(--font-geist-mono), "Fira Code", "Cascadia Code", ui-monospace, monospace;

  /* ──────────────────────────────────────────────────────────
     TYPOGRAPHY SCALE — semantic names
  ────────────────────────────────────────────────────────── */
  --text-display-size:    2.25rem;  /* 36px */
  --text-display-height:  2.5rem;   /* 40px */
  --text-display-weight:  700;

/**
 * GET /api/booking-links
 *
 * Returns all public booking URLs for the authenticated studio:
 * studio root, per-artist, per-service, and upcoming flash events.
 */
import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { buildStudioBookingUrls } from '@/lib/booking-links/urls'
import { logger } from '@/lib/logger'

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) {
    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
  }

  try {
    const supabase = await createClient()
    const studioId = authUser.studioId

    const [studioResult, artistsResult, servicesResult] = await Promise.all([
      supabase
        .from('studios')
        .select('slug, name, brand_color')
        .eq('id', studioId)
        .single(),
      supabase
        .from('artists')
        .select('id, display_name, avatar_url')
        .eq('studio_id', studioId)
        .eq('status', 'active')
        .order('sort_order', { ascending: true }),
      supabase
        .from('services')
        .select('id, name')
        .eq('studio_id', studioId)
        .eq('is_public', true)
        .order('sort_order', { ascending: true }),
    ])

    if (studioResult.error || !studioResult.data) {
      logger.error({ err: studioResult.error, studioId }, 'booking-links: studio lookup failed')
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    const studioSlug = studioResult.data.slug
    const studioName = studioResult.data.name
    const brandColor = studioResult.data.brand_color
    const artists = artistsResult.data ?? []
    const services = servicesResult.data ?? []

    // Flash events are from Sprint 4A — table may not exist yet. Silently skip if absent.
    let flashEvents: Array<{ id: string; title: string; event_date: string }> = []
    try {
      // Use a raw cast to `unknown` first to avoid TS complaining about unknown table columns.
      const flashResult = await (supabase as unknown as {
        from: (table: string) => {
          select: (cols: string) => {
            eq: (col: string, val: unknown) => {
              gte: (col: string, val: string) => {
                order: (col: string, opts: { ascending: boolean }) => {
                  limit: (n: number) => Promise<{ data: unknown; error: unknown }>
                }
              }
            }
          }
        }
      })
        .from('flash_events')
        .select('id, title, event_date')
        .eq('studio_id', studioId)
        .gte('event_date', new Date().toISOString().split('T')[0] ?? '')
        .order('event_date', { ascending: true })
        .limit(10)

      if (!flashResult.error && Array.isArray(flashResult.data)) {
        flashEvents = flashResult.data as Array<{ id: string; title: string; event_date: string }>
      }
    } catch {
      // Flash events table may not be migrated yet — skip gracefully
    }

    const urls = buildStudioBookingUrls(studioSlug, artists, services, flashEvents)
    return NextResponse.json({ data: { ...urls, brandColor, studioName } })
  } catch (err) {
