import { NextResponse } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { listFlashEvents } from '@/lib/flash-events/queries'
import { createFlashEvent } from '@/lib/flash-events/mutations'
import { flashEventCreateSchema } from '@/lib/flash-events/schemas'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'

export async function GET(req: Request) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const url = new URL(req.url)
  const status = url.searchParams.get('status') ?? undefined

  try {
    const events = await listFlashEvents(auth.studioId, status ? { status: status as 'upcoming' | 'all' | 'draft' | 'published' | 'completed' | 'cancelled' } : {})
    return NextResponse.json({ data: events })
  } catch (err) {
    logger.error({ err }, 'GET /api/flash-events failed')
    return NextResponse.json({ error: 'Failed to load flash events' }, { status: 500 })
  }
}

export async function POST(req: Request) {
  const ip = req.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await authedRatelimit.limit(ip)
  if (!rl.success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 })
  }

  let body: unknown
  try {
    body = await req.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = flashEventCreateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.errors[0]?.message ?? 'Validation failed' }, { status: 400 })
  }

  try {
    const event = await createFlashEvent(auth.studioId, parsed.data)
    return NextResponse.json({ data: event }, { status: 201 })
  } catch (err) {
    logger.error({ err }, 'POST /api/flash-events failed')
    const message = err instanceof Error ? err.message : 'Failed to create event'
    return NextResponse.json({ error: message }, { status: 500 })
  }
}

