toolUseResult.originalFile:
/**
 * Instagram / Meta Graph webhook handler.
 *
 * GET  — Meta subscription verification challenge.
 * POST — Inbound IG DM ingest.
 *        - Verifies X-Hub-Signature-256 HMAC-SHA256
 *        - Routes entry.id (page_id) → studio via studio_instagram_pages table
 *        - Matches client by instagram_psid column on clients table
 *        - Calls find_or_create_conversation RPC → inserts comm → triage → auto-reply
 *
 * Feature gate: omnichannel_inbox (Studio+).
 * Type note: new tables (studio_instagram_pages, instagram_psid) and RPCs use
 *            rawDb() wrapper below until pnpm db:types after migration 20260425100000.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { triageConversation, fireAutoReplyIfMatched } from '@/lib/messaging/triage'

// ─── Raw DB helper (new-migration tables not yet in lib/supabase/types.ts) ────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

type RawChain = {
  eq(col: string, val: string): RawChain
  limit(n: number): { maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }> }
  maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }>
  single(): Promise<{ data: Record<string, string> | null; error: unknown }>
}

type RawClient = {
  from(table: string): {
    select(cols: string): RawChain
    insert(row: Record<string, unknown>): {
      select(cols: string): {
        single(): Promise<{ data: Record<string, string> | null; error: unknown }>
      }
    }
    update(patch: Record<string, unknown>): {
      eq(col: string, val: string): Promise<{ error: unknown }>
    }
  }
  rpc(fn: string, args: Record<string, string | null>): Promise<{ data: unknown; error: unknown }>
}

function rawDb(supabase: ServiceClient): RawClient {
  return supabase as unknown as RawClient
}

// ─── Meta IG DM payload types ─────────────────────────────────────────────────

interface MetaAttachment {
  type: string
  payload?: { url?: string } | undefined
}

interface MetaMessage {
  mid: string
  text?: string | undefined
  attachments?: MetaAttachment[] | undefined
}

interface MetaMessagingEntry {
  sender: { id: string }
  recipient: { id: string }
  timestamp: number
  message?: MetaMessage | undefined
}

interface MetaEntry {
  id: string
  time: number
  messaging?: MetaMessagingEntry[] | undefined
}

interface MetaWebhookPayload {
  object: string
  entry: MetaEntry[]
}

// ─── GET — Meta subscription verification ─────────────────────────────────────

export async function GET(request: NextRequest): Promise<NextResponse> {
  const { searchParams } = new URL(request.url)
  const mode = searchParams.get('hub.mode')
  const token = searchParams.get('hub.verify_token')
  const challenge = searchParams.get('hub.challenge')

  if (mode === 'subscribe' && token === process.env.META_WEBHOOK_VERIFY_TOKEN) {
    logger.info({}, 'instagram-webhook: subscription verified')
    return new NextResponse(challenge ?? '', {
      status: 200,
      headers: { 'Content-Type': 'text/plain' },
    })
  }

  logger.warn({ mode }, 'instagram-webhook: verification failed')
  return new NextResponse('Forbidden', { status: 403 })
}

// ─── POST — Inbound IG DM ─────────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(`ig:${ip}`)
  if (!rl.success) return new NextResponse('Too many requests', { status: 429 })

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const appSecret = process.env.META_APP_SECRET
  if (!appSecret) {
    logger.error({}, 'instagram-webhook: META_APP_SECRET not set')
    return new NextResponse(JSON.stringify({ error: 'Webhook not configured' }), {
      status: 503, headers: { 'Content-Type': 'application/json' },
    })
  }

  const signature = request.headers.get('x-hub-signature-256') ?? ''
  const sigBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expected = createHmac('sha256', appSecret).update(rawBody).digest()

  if (sigBuffer.length !== expected.length || !timingSafeEqual(sigBuffer, expected)) {
    logger.warn({}, 'instagram-webhook: invalid X-Hub-Signature-256')
    return new NextResponse('Forbidden', { status: 403 })
  }

  let payload: MetaWebhookPayload
  try {
    payload = JSON.parse(rawBody) as MetaWebhookPayload
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  if (payload.object !== 'instagram' && payload.object !== 'page') {
    return new NextResponse(null, { status: 200 })
  }

  const supabase = createServiceRoleClient()

  for (const entry of payload.entry ?? []) {
    for (const messaging of entry.messaging ?? []) {
      if (!messaging.message) continue
      await handleInboundDm(supabase, entry.id, messaging.sender.id, messaging.message)
        .catch((err: unknown) => logger.error({ err, pageId: entry.id }, 'instagram-webhook: ingest error'))
    }
  }

  return new NextResponse(null, { status: 200 })
}

// ─── handleInboundDm ─────────────────────────────────────────────────────────

async function handleInboundDm(
  supabase: ServiceClient,
  pageId: string,
  senderPsid: string,
  message: MetaMessage,
): Promise<void> {
  const db = rawDb(supabase)

  // 1. Resolve studio from page_id
  const { data: pageRow } = await db
    .from('studio_instagram_pages')
    .select('studio_id')
    .eq('page_id', pageId)
    .maybeSingle()
  const studioId = pageRow?.studio_id ?? null
  if (!studioId) {
    logger.warn({ pageId }, 'instagram-webhook: no studio mapped to page_id — dropped')
    return
  }

  // 2. Match client by instagram_psid
  const { data: clientRow } = await db
    .from('clients')
    .select('id')
    .eq('instagram_psid', senderPsid)
    .eq('studio_id', studioId)
    .maybeSingle()
  const clientId = clientRow?.id ?? null

  // 3. Find or create conversation
  const { data: convData, error: rpcError } = await db.rpc('find_or_create_conversation', {
    p_studio_id: studioId,
    p_channel: 'instagram',
    p_external_identifier: senderPsid,
    p_client_id: clientId,
  })
  if (rpcError || !convData) {
    logger.error({ err: rpcError, senderPsid, studioId }, 'instagram-webhook: find_or_create_conversation failed')
    return
  }
  const conversationId = convData as string

  // 4. Skip insert if no client (FK constraint)
  if (!clientId) {
    logger.warn({ senderPsid, studioId }, 'instagram-webhook: unknown psid — conv created but comm not stored')
    return
  }

  const body = message.text ?? (message.attachments?.[0]?.type ?? '(attachment)')
  const mediaUrls = (message.attachments ?? [])
    .map((a) => a.payload?.url)
    .filter((u): u is string => Boolean(u))

  // 5. Insert inbound comm
  const { data: insertedComm, error: insertError } = await db
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId,
      channel: 'instagram',
      direction: 'inbound',
      body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      provider_message_id: message.mid,
      metadata: { ig_message_mid: message.mid, ...(mediaUrls.length > 0 && { media_urls: mediaUrls }) },
    })
    .select('id')
    .single()

  if (insertError || !insertedComm) {
    logger.error({ err: insertError, senderPsid }, 'instagram-webhook: comm insert failed')
    return
  }

  logger.info({ senderPsid, studioId, conversationId }, 'instagram-webhook: inbound DM stored')

  // 6. Triage + auto-reply (non-fatal)
  try { await triageConversation(studioId, conversationId) }
  catch (err) { logger.error({ err, conversationId }, 'instagram-webhook: triage failed (non-fatal)') }

  const commId = insertedComm.id
  if (commId) {
    try { await fireAutoReplyIfMatched(studioId, conversationId, commId) }
    catch (err) { logger.error({ err, conversationId }, 'instagram-webhook: auto-reply failed (non-fatal)') }
  }
}

