toolUseResult.originalFile:
/**
 * WhatsApp / Meta Cloud API webhook handler.
 *
 * GET  — Meta subscription verification challenge.
 * POST — Inbound WA message ingest.
 *        - Verifies X-Hub-Signature-256 (META_WHATSAPP_APP_SECRET)
 *        - Routes phone_number_id → studio via studio_whatsapp_numbers table
 *        - Matches client by phone (E.164, same as SMS)
 *        - Calls find_or_create_conversation RPC → inserts comm → triage → auto-reply
 *
 * Feature gate: omnichannel_inbox (Studio+).
 * Type note: studio_whatsapp_numbers uses rawDb() wrapper until pnpm db:types after migration.
 */

import { type NextRequest, NextResponse } from 'next/server'
import { createHmac, timingSafeEqual } from 'crypto'
import { createServiceRoleClient } from '@/lib/supabase/server'
import { apiRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { triageConversation, fireAutoReplyIfMatched } from '@/lib/messaging/triage'

// ─── Raw DB helper ────────────────────────────────────────────────────────────

type ServiceClient = ReturnType<typeof createServiceRoleClient>

type RawChain = {
  eq(col: string, val: string): RawChain
  limit(n: number): { maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }> }
  maybeSingle(): Promise<{ data: Record<string, string> | null; error: unknown }>
  single(): Promise<{ data: Record<string, string> | null; error: unknown }>
}

type RawClient = {
  from(table: string): {
    select(cols: string): RawChain
    insert(row: Record<string, unknown>): {
      select(cols: string): {
        single(): Promise<{ data: Record<string, string> | null; error: unknown }>
      }
    }
    update(patch: Record<string, unknown>): {
      eq(col: string, val: string): Promise<{ error: unknown }>
    }
  }
  rpc(fn: string, args: Record<string, string | null>): Promise<{ data: unknown; error: unknown }>
}

function rawDb(supabase: ServiceClient): RawClient {
  return supabase as unknown as RawClient
}

// ─── Meta WA payload types ────────────────────────────────────────────────────

interface WaTextMessage { body: string }
interface WaImageMessage { id: string; mime_type: string; caption?: string }

interface WaMessage {
  id: string
  from: string
  type: string
  timestamp: string
  text?: WaTextMessage | undefined
  image?: WaImageMessage | undefined
}

interface WaStatus {
  id: string
  status: 'sent' | 'delivered' | 'read' | 'failed'
  timestamp: string
  recipient_id: string
}

interface WaMetadata {
  display_phone_number: string
  phone_number_id: string
}

interface WaChangeValue {
  messaging_product: string
  metadata: WaMetadata
  messages?: WaMessage[] | undefined
  statuses?: WaStatus[] | undefined
}

interface WaEntry {
  id: string
  changes: { value: WaChangeValue; field: string }[]
}

interface WaWebhookPayload {
  object: string
  entry: WaEntry[]
}

// ─── GET — Meta subscription verification ─────────────────────────────────────

export async function GET(request: NextRequest): Promise<NextResponse> {
  const { searchParams } = new URL(request.url)
  const mode = searchParams.get('hub.mode')
  const token = searchParams.get('hub.verify_token')
  const challenge = searchParams.get('hub.challenge')

  const verifyToken = process.env.META_WHATSAPP_WEBHOOK_VERIFY_TOKEN ?? process.env.META_WEBHOOK_VERIFY_TOKEN

  if (mode === 'subscribe' && token === verifyToken) {
    logger.info({}, 'whatsapp-webhook: subscription verified')
    return new NextResponse(challenge ?? '', {
      status: 200,
      headers: { 'Content-Type': 'text/plain' },
    })
  }

  logger.warn({ mode }, 'whatsapp-webhook: verification failed')
  return new NextResponse('Forbidden', { status: 403 })
}

// ─── POST — Inbound WA message ────────────────────────────────────────────────

export async function POST(request: NextRequest): Promise<NextResponse> {
  const ip = request.headers.get('x-forwarded-for') ?? 'unknown'
  const rl = await apiRatelimit.limit(`wa:${ip}`)
  if (!rl.success) return new NextResponse('Too many requests', { status: 429 })

  let rawBody: string
  try {
    rawBody = await request.text()
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  const appSecret = process.env.META_WHATSAPP_APP_SECRET ?? process.env.META_APP_SECRET
  if (!appSecret) {
    logger.error({}, 'whatsapp-webhook: app secret not set')
    return new NextResponse(JSON.stringify({ error: 'Webhook not configured' }), {
      status: 503, headers: { 'Content-Type': 'application/json' },
    })
  }

  const signature = request.headers.get('x-hub-signature-256') ?? ''
  const sigBuffer = Buffer.from(signature.replace('sha256=', ''), 'hex')
  const expected = createHmac('sha256', appSecret).update(rawBody).digest()

  if (sigBuffer.length !== expected.length || !timingSafeEqual(sigBuffer, expected)) {
    logger.warn({}, 'whatsapp-webhook: invalid X-Hub-Signature-256')
    return new NextResponse('Forbidden', { status: 403 })
  }

  let payload: WaWebhookPayload
  try {
    payload = JSON.parse(rawBody) as WaWebhookPayload
  } catch {
    return new NextResponse('Bad request', { status: 400 })
  }

  if (payload.object !== 'whatsapp_business_account') {
    return new NextResponse(null, { status: 200 })
  }

  const supabase = createServiceRoleClient()

  for (const entry of payload.entry ?? []) {
    for (const change of entry.changes ?? []) {
      if (change.field !== 'messages') continue
      const { value } = change

      for (const msg of value.messages ?? []) {
        await handleInboundMessage(supabase, value.metadata.phone_number_id, msg)
          .catch((err: unknown) => logger.error({ err, phoneNumberId: value.metadata.phone_number_id }, 'whatsapp-webhook: ingest error'))
      }

      for (const status of value.statuses ?? []) {
        await handleStatusUpdate(supabase, status)
          .catch((err: unknown) => logger.error({ err, statusId: status.id }, 'whatsapp-webhook: status error'))
      }
    }
  }

  return new NextResponse(null, { status: 200 })
}

// ─── handleStatusUpdate ───────────────────────────────────────────────────────

async function handleStatusUpdate(supabase: ServiceClient, status: WaStatus): Promise<void> {
  const mappedStatus = (status.status === 'delivered' || status.status === 'read') ? 'delivered'
    : status.status === 'sent' ? 'sent' : 'failed'

  const db = rawDb(supabase)
  await db
    .from('client_communications')
    .update({
      status: mappedStatus,
      ...(mappedStatus === 'delivered' && { delivered_at: new Date().toISOString() }),
    })
    .eq('provider_message_id', status.id)
}

// ─── handleInboundMessage ─────────────────────────────────────────────────────

async function handleInboundMessage(
  supabase: ServiceClient,
  phoneNumberId: string,
  msg: WaMessage,
): Promise<void> {
  const db = rawDb(supabase)

  // 1. Resolve studio from phone_number_id
  const { data: numRow } = await db
    .from('studio_whatsapp_numbers')
    .select('studio_id')
    .eq('phone_number_id', phoneNumberId)
    .maybeSingle()
  const studioId = numRow?.studio_id ?? null
  if (!studioId) {
    logger.warn({ phoneNumberId }, 'whatsapp-webhook: no studio mapped — dropped')
    return
  }

  // 2. Match client by from (E.164)
  const { data: clientRow } = await db
    .from('clients')
    .select('id')
    .eq('studio_id', studioId)
    .eq('phone', msg.from)
    .limit(1)
    .maybeSingle()
  const clientId = clientRow?.id ?? null

  // 3. Find or create conversation
  const { data: convData, error: rpcError } = await db.rpc('find_or_create_conversation', {
    p_studio_id: studioId,
    p_channel: 'whatsapp',
    p_external_identifier: msg.from,
    p_client_id: clientId,
  })
  if (rpcError || !convData) {
    logger.error({ err: rpcError, from: msg.from, studioId }, 'whatsapp-webhook: find_or_create_conversation failed')
    return
  }
  const conversationId = convData as string

  // 4. Skip insert if no client
  if (!clientId) {
    logger.warn({ from: msg.from, studioId }, 'whatsapp-webhook: unknown sender — comm not stored')
    return
  }

  const body = msg.text?.body ?? msg.image?.caption ?? `(${msg.type} message)`

  // 5. Insert inbound comm
  const { data: insertedComm, error: insertError } = await db
    .from('client_communications')
    .insert({
      studio_id: studioId,
      client_id: clientId,
      conversation_id: conversationId,
      channel: 'whatsapp',
      direction: 'inbound',
      body,
      status: 'delivered',
      sent_at: new Date().toISOString(),
      delivered_at: new Date().toISOString(),
      provider_message_id: msg.id,
      metadata: { wa_message_id: msg.id, wa_type: msg.type },
    })
    .select('id')
    .single()

  if (insertError || !insertedComm) {
    logger.error({ err: insertError, from: msg.from }, 'whatsapp-webhook: comm insert failed')
    return
  }

  logger.info({ from: msg.from, studioId, conversationId }, 'whatsapp-webhook: inbound message stored')

  // 6. Triage + auto-reply (non-fatal)
  try { await triageConversation(studioId, conversationId) }
  catch (err) { logger.error({ err, conversationId }, 'whatsapp-webhook: triage failed (non-fatal)') }

  const commId = insertedComm.id
  if (commId) {
    try { await fireAutoReplyIfMatched(studioId, conversationId, commId) }
    catch (err) { logger.error({ err, conversationId }, 'whatsapp-webhook: auto-reply failed (non-fatal)') }
  }
}

